  public void fillTiles(final int distance)
  {
    if (!getSourceCell().isFilled())
    {
      fillBeginTile();
    }

    int newlyFilled = 0;
    EList<Coordinate> frontier = new org.eclipse.emf.common.util.BasicEList<Coordinate>();
    frontier.addAll(getFilledTiles());

    int remaining = distance;
    while (remaining-- > 0 && !frontier.isEmpty())
    {
      EList<Coordinate> nextFrontier = new org.eclipse.emf.common.util.BasicEList<Coordinate>();
      for (Coordinate coord : frontier)
      {
        int row = coord.getRow();
        int col = coord.getCol();
        int[][] deltas = new int[][] { { -1, 0 }, { 1, 0 }, { 0, -1 }, { 0, 1 } };
        for (int[] delta : deltas)
        {
          int nr = row + delta[0];
          int nc = col + delta[1];
          if (nr < 1 || nr > getRows() - 2 || nc < 1 || nc > getCols() - 2)
          {
            continue;
          }
          Cell neighborCell = getCell()[nr][nc];
          if (!(neighborCell instanceof FillableCell))
          {
            continue;
          }
          FillableCell currentCell = (FillableCell)getCell()[row][col];
          FillableCell neighbor = (FillableCell)neighborCell;
          Pipe currentPipe = currentCell.getPipe();
          Pipe neighborPipe = neighbor.getPipe();
          if (currentPipe == null || neighborPipe == null || neighborPipe.isFilled())
          {
            continue;
          }
          Direction fromDir = null;
          Direction toDir = null;
          if (delta[0] == -1)
          {
            fromDir = Direction.UP;
            toDir = Direction.DOWN;
          }
          else if (delta[0] == 1)
          {
            fromDir = Direction.DOWN;
            toDir = Direction.UP;
          }
          else if (delta[1] == -1)
          {
            fromDir = Direction.LEFT;
            toDir = Direction.RIGHT;
          }
          else if (delta[1] == 1)
          {
            fromDir = Direction.RIGHT;
            toDir = Direction.LEFT;
          }
          if (currentPipe.getConnections().contains(fromDir) && neighborPipe.getConnections().contains(toDir))
          {
            neighborPipe.setFilled(true);
            Coordinate newCoord = Pa19Factory.eINSTANCE.createCoordinate();
            newCoord.setRow(nr);
            newCoord.setCol(nc);
            getFilledTiles().add(newCoord);
            nextFrontier.add(newCoord);
            newlyFilled++;
          }
        }
      }
      frontier = nextFrontier;
    }

    this.prevFilledDistance = distance;
    this.prevFilledTiles = newlyFilled;
    
  }

